/**
 * Logger Initialization - Integrates SupabaseAdapter as JellyLogger Transport
 * Ensures all logger.info(), logger.error() calls route through SupabaseAdapter
 */

import { initializeLogger, SupabaseAdapter, getTransport } from "@jelly/adapters";
import { JellyLogger } from "@jelly/logger";
import { supabase } from "../lib/supabase";

/**
 * Setup logger with Supabase transport integration
 * Gets the active JellyLogger instance and adds SupabaseTransport
 */
export function setupLogger() {
  try {
    const adapter = new SupabaseAdapter({
      supabase: {
        client: supabase,
        table: "logs",
        url: import.meta.env.VITE_SUPABASE_URL,
        anonKey: import.meta.env.VITE_SUPABASE_ANON_KEY,
      },
      batchSize: 50,
      flushInterval: 5000,
    });

    // Get the active JellyLogger instance and pass to initializeLogger
    // This ensures the SupabaseTransport is added to the logger
    try {
      const logger = JellyLogger.getInstance();
      initializeLogger(adapter, logger);
      console.log("[Logger] SupabaseAdapter initialized with transport integration");
    } catch {
      // Logger not yet initialized, initialize adapter without logger
      initializeLogger(adapter);
      console.log("[Logger] SupabaseAdapter initialized (logger will be configured later)");
    }
  } catch (error) {
    console.error("[Logger] Failed to setup logger:", error);
  }
}

/**
 * Get the SupabaseTransport for manual operations
 */
export function getLoggerTransport() {
  return getTransport();
}

/**
 * Get adapter for advanced operations
 */
export { getAdapter } from "@jelly/adapters";
