import { SupabaseAdapter } from "./adapter";
import { SupabaseTransport } from "./supabase-transport";
import type { JellyLogger } from "@jelly/logger";

let globalAdapter: SupabaseAdapter | null = null;
let globalTransport: SupabaseTransport | null = null;

/**
 * Initialize logger with SupabaseAdapter and integrate as transport
 */
export function initializeLogger(
  adapter: SupabaseAdapter,
  logger?: JellyLogger,
): void {
  globalAdapter = adapter;
  globalTransport = new SupabaseTransport(adapter);

  adapter.test().catch(() => {
    console.warn("[Logger] Supabase adapter test failed");
  });

  if (logger) {
    logger.addTransport(globalTransport);
  }
}

/**
 * Get the global adapter instance
 */
export function getAdapter(): SupabaseAdapter {
  if (!globalAdapter) {
    throw new Error("Logger adapter not initialized. Call initializeLogger() first.");
  }
  return globalAdapter;
}

/**
 * Get the global transport instance
 */
export function getTransport(): SupabaseTransport {
  if (!globalTransport) {
    throw new Error("Logger transport not initialized. Call initializeLogger() first.");
  }
  return globalTransport;
}

export { SupabaseAdapter, SupabaseTransport };
export type { LogEntry } from "./adapter";
