import { SupabaseAdapter, type LogEntry } from './adapter';
import type { ITransport } from '@jelly/logger';
import type { ILogEntry } from '@jelly/logger';

/**
 * SupabaseTransport - Integrates SupabaseAdapter with @jelly/logger
 * Implements ITransport interface for seamless integration
 * All logger.info(), logger.error() calls automatically route through SupabaseAdapter
 */
export class SupabaseTransport implements ITransport {
  name: string = 'supabase';
  enabled: boolean = true;

  constructor(private adapter: SupabaseAdapter) {}

  /**
   * Send a single log entry to Supabase via adapter's queue
   */
  async send(entry: ILogEntry): Promise<void> {
    const logEntry = this.convertEntry(entry);
    this.adapter.enqueue(logEntry);
  }

  /**
   * Send batch of log entries to Supabase
   */
  async batch(entries: ILogEntry[]): Promise<void> {
    for (const entry of entries) {
      const logEntry = this.convertEntry(entry);
      this.adapter.enqueue(logEntry);
    }
    // Flush immediately after batch
    await this.adapter.flush();
  }

  /**
   * Flush any queued logs to Supabase
   */
  async flush(): Promise<void> {
    await this.adapter.flush();
  }

  /**
   * Close transport (flush any remaining logs)
   */
  async close(): Promise<void> {
    await this.adapter.destroy();
  }

  /**
   * Convert ILogEntry from @jelly/logger to LogEntry for SupabaseAdapter
   */
  private convertEntry(entry: ILogEntry): LogEntry {
    return {
      id: entry.id,
      timestamp: this.formatTimestamp(entry.timestamp),
      level: entry.level,
      message: entry.message,
      context: entry.context || {},
      severity: entry.severity || 'INFO',
      source: entry.source || 'unknown',
      user_id: entry.userId || null,
      session_id: entry.sessionId || null,
      request_id: entry.requestId || null,
      correlation_id: entry.correlationId || null,
      url: entry.url || null,
      user_agent: entry.userAgent || null,
      ip_address: entry.ipAddress || null,
      device_info: entry.deviceInfo || null,
      tags: entry.tags || null,
      duration_ms: entry.durationMs || null,
      meta: entry.meta,
      stack_trace: entry.stackTrace || null,
    };
  }

  /**
   * Format timestamp to ISO string for database
   */
  private formatTimestamp(timestamp: number | Date): string {
    if (typeof timestamp === 'number') {
      return new Date(timestamp).toISOString();
    }
    return timestamp.toISOString();
  }
}
