import { isValidUUID } from "@jelly/context";
import type { SupabaseClient } from "@supabase/supabase-js";

export interface LogEntry {
  id?: string;
  timestamp: string;
  level: string;
  message: string;
  context?: Record<string, any>;
  severity: string;
  source: string;
  user_id?: string | null;
  session_id?: string | null;
  request_id?: string | null;
  correlation_id?: string | null;
  url?: string | null;
  user_agent?: string | null;
  ip_address?: string | null;
  device_info?: Record<string, any> | null;
  tags?: string[] | null;
  duration_ms?: number | null;
  [key: string]: any;
}

export class SupabaseAdapter {
  private supabaseClient: SupabaseClient;
  private table: string;
  private queue: LogEntry[] = [];
  private timer: ReturnType<typeof setTimeout> | null = null;
  private batchSize: number;
  private flushInterval: number;

  constructor(config: any) {
    this.supabaseClient =
      config.supabase.client ||
      require("@supabase/supabase-js").createClient(
        config.supabase.url,
        config.supabase.anonKey,
      );
    this.table = config.supabase.table || "logs";
    this.batchSize = config.batchSize || 50;
    this.flushInterval = config.flushInterval || 5000;
  }

  private validateEntry(entry: LogEntry): LogEntry {
    return {
      ...entry,
      user_id: isValidUUID(entry.user_id) ? entry.user_id : null,
      session_id: isValidUUID(entry.session_id) ? entry.session_id : null,
      request_id: isValidUUID(entry.request_id) ? entry.request_id : null,
      correlation_id: isValidUUID(entry.correlation_id)
        ? entry.correlation_id
        : null,
    };
  }

  async insert(entry: LogEntry): Promise<void> {
    const validated = this.validateEntry(entry);
    const { error } = await this.supabaseClient
      .from(this.table)
      .insert([validated]);
    if (error) throw new Error(`Supabase insert failed: ${error.message}`);
  }

  enqueue(entry: LogEntry): void {
    this.queue.push(entry);
    if (this.queue.length >= this.batchSize) {
      this.flush();
    } else if (!this.timer) {
      this.timer = setTimeout(() => this.flush(), this.flushInterval);
    }
  }

  async flush(): Promise<void> {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    if (this.queue.length === 0) return;

    const entries = this.queue.splice(0, this.batchSize);
    try {
      for (const entry of entries) {
        await this.insert(entry);
      }
    } catch (error) {
      this.queue.unshift(...entries);
      console.error("[Logger] Batch insert failed:", (error as Error).message);
    }
  }

  async test(): Promise<boolean> {
    try {
      const { error } = await this.supabaseClient
        .from(this.table)
        .select("id")
        .limit(1);
      return !error;
    } catch {
      return false;
    }
  }

  async destroy(): Promise<void> {
    await this.flush();
  }
}
